draw((11.5,0)--(11.5,0.5)--(12,0.5), r);
label(scale(0.75)*"5", (2, 2.2), r);
label(scale(0.75)*"5", (14, 2.2), r);
label(scale(0.75)*"4", (2, 0), S, r);
label(scale(0.75)*"4", (14, 0), S, r);
